#include "ark/agent.hpp"
#include "ark/agent_team.hpp"
#include <chrono>
#include <iostream>
#include <stdexcept>
using namespace ark;using V=arkjson::Value;
namespace {
void check(bool b,const char* message){if(!b)throw std::runtime_error(message);}
V json(const std::string& text){V value;check(arkjson::parse(text,value),"JSON parses");return value;}
V accepted(const V& response){if(response.find("isError")->b)throw std::runtime_error(response.find("structuredContent")->dump());return *response.find("structuredContent");}
V call(AgentSession& s,const char* tool,const std::string& args){return accepted(s.call(tool,json(args)));}
V proposal(u64 revision,double width){V args=json(R"({"id":"Part","rule_id":"DFM.FDM.02","rule_version":1,"commands":[{"op":"feature.edit","id":"Part","p":{"width":18}}]})");args.set("expected_revision",V::makeNum((double)revision));auto commands=*args.find("commands");auto p=*commands.arr[0].find("p");p.set("width",V::makeNum(width));commands.arr[0].set("p",p);args.set("commands",commands);return args;}
void discovery(){bool found=false;for(const auto& tool:AgentSession::tools().arr)if(tool.find("name")->str=="manufacturing_propose"){found=true;check(tool.find("annotations")->find("readOnlyHint")->b,"proposal is read-only CAD");check(tool.find("inputSchema")->find("properties")->find("commands")->find("maxItems")->num==8,"bounded editable proposal schema");}check(found,"proposal discoverable");AgentSession s;const auto saved=documentToJson(s.document);check(s.call("manufacturing_propose",proposal(1,18)).find("isError")->b&&s.revision==0&&saved==documentToJson(s.document),"stale proposal rejects without mutation");}
#ifdef ARK_DFM_NATIVE_TESTS
void initialize(AgentSession& s){call(s,"doc_apply",R"({"expected_revision":0,"commands":[{"op":"feature.add","type":"native_solid","name":"Part","native":{"op":"box"},"p":{"width":20,"depth":10,"height":5},"manufacturing":{"route":"additive","process":{"method":"fdm","layer_height_mm":0.2,"nozzle_diameter_mm":0.4,"build_direction":[0,0,1],"build_volume_mm":[19,10,5]}}}]})");}
void exactWorkflow(){
    AgentSession s;initialize(s);const auto saved=documentToJson(s.document);const auto generation=s.document.evaluationGeneration;auto prepared=accepted(s.call("manufacturing_propose",proposal(s.revision,18)));const auto& compared=*prepared.find("dfm_comparison");
    check(prepared.find("valid")->b&&prepared.find("candidate_cached")->b&&compared.find("target_screen_resolved")->b,"actual exact candidate resolves FDM envelope screen");check(compared.find("baseline_revision")->num==1&&compared.find("before")->find("revision")->num==1&&compared.find("after")->find("revision")->num==1&&compared.find("same_process_inputs")->b,"comparison bound to one revision and same process inputs");const auto& before=compared.find("before")->find("components")->arr[0];const auto& after=compared.find("after")->find("components")->arr[0];check(before.find("geometry")->find("bounds_mm")->arr[3].num==20&&after.find("geometry")->find("bounds_mm")->arr[3].num==18,"comparison retains exact geometry before/after");check(before.find("process")->dump()==after.find("process")->dump(),"capabilities not relaxed by candidate");check(!compared.find("manufacturing_qualified")->b&&!compared.find("cost_improvement_claimed")->b&&!compared.find("design_improvement_claimed")->b&&!compared.find("unresolved")->arr.empty(),"unknown production evidence retained without improvement claim");check(saved==documentToJson(s.document)&&generation==s.document.evaluationGeneration&&s.revision==1,"proposal leaves live document geometry and revision unchanged");
    V apply=*prepared.find("apply");apply.obj.erase(std::remove_if(apply.obj.begin(),apply.obj.end(),[](const auto& field){return field.first=="accept_dfm";}),apply.obj.end());check(s.call("doc_apply",apply).find("isError")->b&&saved==documentToJson(s.document)&&s.revision==1,"missing explicit acceptance rejects atomically");apply.set("accept_dfm",V::makeBool(false));check(s.call("doc_apply",apply).find("isError")->b&&saved==documentToJson(s.document),"explicit rejection preserves live design");auto commit=accepted(s.call("doc_apply",*prepared.find("apply")));check(s.revision==2&&commit.find("dfm_accepted")->b&&commit.find("applied_prepared")->b&&!commit.find("geometry_recomputed")->b,"explicit accepted candidate commits atomically without reevaluation");check(call(s,"manufacturing_inspect",R"({"id":"Part"})").find("components")->arr[0].find("geometry")->find("bounds_mm")->arr[3].num==18,"accepted design retains measured exact dimensions");call(s,"doc_undo","{}");check(s.document.features[0].p.at("width")=="20","one undo restores entire proposal");
}
void rejections(){
    AgentSession s;initialize(s);const auto saved=documentToJson(s.document);auto reject=[&](const V& args){check(s.call("manufacturing_propose",args).find("isError")->b&&s.revision==1&&saved==documentToJson(s.document),"invalid proposal rejects without mutation");};V args=proposal(0,18);reject(args);args=proposal(1,18);args.set("rule_version",V::makeNum(2));reject(args);args=proposal(1,18);args.set("rule_id",V::makeStr("DFM.CNC.01"));reject(args);args=proposal(1,18);args.set("rule_id",V::makeStr("DFM.FDM.01"));reject(args);args=proposal(1,18);args.set("commands",json(R"([{"op":"feature.edit","id":"Part","manufacturing":{"route":"additive","process":{"build_volume_mm":[100,100,100]}}}])"));reject(args);args.set("commands",json(R"([{"op":"feature.remove","id":"Part"}])"));reject(args);args=proposal(1,18);args.set("commands",json(R"([{"op":"feature.edit","id":"Part","p":{"density":2}}])"));reject(args);args=proposal(1,18);args.set("commands",json(R"([{"op":"param.set","name":"unrelated","expr":3}])"));reject(args);args=proposal(1,20);reject(args);
    args=proposal(1,-1);auto invalid=accepted(s.call("manufacturing_propose",args));check(!invalid.find("valid")->b&&!invalid.find("candidate_id")&&saved==documentToJson(s.document),"failed geometry produces inspectable failure and no candidate");args=proposal(1,18);args.set("checks",json(R"([{"query":{"tool":"manufacturing_inspect","args":{"id":"Part"},"path":"components.0.manufacturing_qualified"},"op":"true"}])"));invalid=accepted(s.call("manufacturing_propose",args));check(!invalid.find("valid")->b&&!invalid.find("candidate_id")&&saved==documentToJson(s.document),"failed required check prevents preparation");
    auto worse=accepted(s.call("manufacturing_propose",proposal(1,22)));check(!worse.find("dfm_comparison")->find("target_screen_resolved")->b,"worsened design never claims target resolved");auto prepared=accepted(s.call("manufacturing_propose",proposal(1,18)));call(s,"doc_apply",R"({"expected_revision":1,"commands":[{"op":"param.set","name":"unrelated","expr":1}]})");const auto changed=documentToJson(s.document);check(s.call("doc_apply",*prepared.find("apply")).find("isError")->b&&s.revision==2&&documentToJson(s.document)==changed,"stale candidate cannot rebase or mutate");
    AgentSession legacy;call(legacy,"doc_apply",R"({"expected_revision":0,"commands":[{"op":"feature.add","type":"box","name":"Part","p":{"dx":20,"dy":10,"dz":5},"manufacturing":{"route":"purchased"}}]})");check(legacy.call("manufacturing_propose",proposal(1,18)).find("isError")->b,"display mesh never supplies exact proposal evidence");
}
void collateralEvidence(){AgentSession s;call(s,"doc_apply",R"({"expected_revision":0,"commands":[{"op":"param.set","name":"span","expr":20},{"op":"feature.add","type":"native_solid","name":"Part","native":{"op":"box"},"p":{"width":"span","depth":10,"height":5},"manufacturing":{"route":"additive","process":{"method":"fdm","build_direction":[0,0,1],"build_volume_mm":[19,10,5]}}},{"op":"feature.add","type":"native_solid","name":"Other","native":{"op":"box"},"p":{"width":"40-span","depth":10,"height":5},"manufacturing":{"route":"machined","process":{"stock_size_mm":[21,10,5],"stock_origin_mm":[0,0,0]}}}]})");V args=proposal(1,18);args.set("commands",json(R"([{"op":"param.set","name":"span","expr":18}])"));auto result=accepted(s.call("manufacturing_propose",args));bool regression=false;for(const auto& row:result.find("dfm_comparison")->find("rule_transitions")->arr)if(row.find("rule_id")->str=="DFM.CNC.01"&&row.find("before_status")->str=="compatible"&&row.find("after_status")->str=="incompatible")regression=true;check(regression&&result.find("dfm_comparison")->find("target_screen_resolved")->b&&s.revision==1,"all-component report exposes collateral regression despite target screen resolution");}
void retainedIdentity(){AgentSession s;initialize(s);auto initial=accepted(s.call("manufacturing_propose",proposal(1,18)));for(int n=0;n<4;++n)accepted(s.call("manufacturing_propose",proposal(1,17-n)));const auto saved=documentToJson(s.document);check(s.call("doc_apply",*initial.find("apply")).find("isError")->b&&documentToJson(s.document)==saved,"evicted candidate rejects without mutation");auto current=accepted(s.call("manufacturing_propose",proposal(1,18)));s.document.features[0].name="Manual name change";const auto manual=documentToJson(s.document);check(s.call("doc_apply",*current.find("apply")).find("isError")->b&&s.revision==1&&documentToJson(s.document)==manual,"same revision with changed document fingerprint rejects");}
void sheetWorkflow(){AgentSession s;call(s,"doc_apply",R"({"expected_revision":0,"commands":[{"op":"sheet.create","name":"Part","p":{"width":30,"thickness":2,"k_factor":0.5},"base":{"id":"base","length":40}},{"op":"sheet.flange.add","id":"Part","flange":{"id":"flange","parent":"base","edge":"u_max","length":20,"inner_radius":1,"angle":90}},{"op":"feature.edit","id":"Part","manufacturing":{"route":"sheet_metal","process":{"cutting_method":"laser","laser_max_thickness_mm":2,"minimum_bend_radius_mm":2}}}]})");V args=proposal(1,18);args.set("rule_id",V::makeStr("DFM.BEND.01"));args.set("commands",json(R"([{"op":"sheet.flange.edit","id":"Part","entity":"flange","values":{"inner_radius":3}}])"));auto result=accepted(s.call("manufacturing_propose",args));check(result.find("dfm_comparison")->find("target_screen_resolved")->b&&s.revision==1,"editable sheet radius changes screen in isolated exact candidate");accepted(s.call("doc_apply",*result.find("apply")));check(s.revision==2,"accepted sheet candidate commits");}
V providerCall(const char* name,const V& args){static int serial=0;V r=json(R"({"status":"completed","output":[{"type":"function_call","call_id":"test"}]})");V output=*r.find("output");output.arr[0].set("call_id",V::makeStr("call-"+std::to_string(++serial)));output.arr[0].set("name",V::makeStr(name));output.arr[0].set("arguments",V::makeStr(args.dump()));r.set("output",output);return r;}
void teamWorkflow(){AgentSession s;initialize(s);AgentTeam team;AgentTeamConfig config;AgentTeamRole writer;writer.id="designer";writer.label="designer";writer.canWrite=true;writer.discipline=AgentTeamDiscipline::PartDesigner;writer.assistant.model="offline-test";int rounds=0;V apply;writer.transport=[&](auto&,auto&,auto*){if(++rounds==1)return providerCall("manufacturing_propose",proposal(1,18));if(rounds==2){V missing=apply;missing.set("accept_dfm",V::makeBool(false));return providerCall("team_apply_step",missing);}if(rounds==3)return providerCall("team_apply_step",apply);return json(R"({"status":"completed","output":[{"type":"message","role":"assistant","content":[{"type":"output_text","text":"Completed explicit offline acceptance fixture"}]}]})");};config.roles={writer};team.start(config,"Review proposal and explicitly accept fixture",AgentSession::tools(),[&](const auto& name,const V& args){auto response=s.call(name,args);if(name=="manufacturing_propose"&&!response.find("isError")->b)apply=*response.find("structuredContent")->find("apply");return response;});check(team.waitIdleFor(std::chrono::seconds(8)),"team fixture completes");if(s.revision!=2||team.snapshot().roles[0].stepsApplied!=1){for(const auto& event:team.snapshot().events)std::cerr<<event.tool<<": "<<event.text<<'\n';std::cerr<<"revision="<<s.revision<<" steps="<<team.snapshot().roles[0].stepsApplied<<'\n';}check(s.revision==2&&team.snapshot().roles[0].stepsApplied==1,"team retains same-role proposal recipe, rejects false acceptance and commits once");}
#endif
}
int main(){try{discovery();
#ifdef ARK_DFM_NATIVE_TESTS
exactWorkflow();rejections();collateralEvidence();retainedIdentity();sheetWorkflow();teamWorkflow();
#endif
std::cout<<"DFM proposals: exact comparison, explicit acceptance, stale rejection and isolation passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
